floor_fn:
"""returns a list for flow control. The list can be mutated outside
    the function and will remain in memory"""
def create_flow_control(n: Any) -> object {
    return ([False] * n);
}

test_blocks:
test "t0" {
    assert (
        create_flow_control(7) == [False, False, False, False, False, False, False]
    );;
}

test "t1" {
    assert (
        create_flow_control(10)
        == [False, False, False, False, False, False, False, False, False, False]
    );;
}

test "t2" {
    assert (create_flow_control(100) == ([False] * 100));;
}

test "t3" {
    assert (create_flow_control(2) == [False, False]);;
}

test "t4" {
    assert (create_flow_control(6) == [False, False, False, False, False, False]);;
}

test "t5" {
    assert (create_flow_control(500) == ([False] * 500));;
}

test "t6" {
    assert (create_flow_control(10) == ([False] * 10));;
}

test "t7" {
    assert (create_flow_control(4) == [False, False, False, False]);;
}

test "t8" {
    assert (create_flow_control(1) == [False]);;
}

test "t9" {
    assert (create_flow_control(50) == ([False] * 50));;
}

test "t10" {
    assert (create_flow_control(0) == []);;
}

test "t11" {
    assert (create_flow_control(20) == ([False] * 20));;
}

test "t12" {
    assert (create_flow_control(-1) == []);;
}

test "t13" {
    assert (create_flow_control(5) == ([False] * 5));;
}

test "t14" {
    assert (create_flow_control(3) == [False, False, False]);;
}

test "t15" {
    assert (create_flow_control(5) == [False, False, False, False, False]);;
}

test "t16" {
    assert (create_flow_control(-10) == []);;
}
